parameters.jsCode:
const raw = $input.first().json.output;
let jsonStr = null;
try {
  const s = raw.indexOf('{');
  const e = raw.lastIndexOf('}');
  if (s === -1 || e === -1) throw new Error('JSON não encontrado');
  jsonStr = raw.substring(s, e + 1);
  const p = JSON.parse(jsonStr);
  return [{
    json: {
      classification: p.classification,
      reason: p.reason,
      name: p.lead_data.name,
      phone: p.lead_data.phone,
      exames_interesse: p.lead_data.exames_interesse || 'Não informado',
      convenio: p.lead_data.convenio || 'Não informado',
      urgencia: p.lead_data.urgencia || 'Não informado',
      motivo_handoff: p.lead_data.motivo_handoff || 'Não informado',
      last_context: p.lead_data.last_context || ''
    }
  }];
} catch (err) {
  return [{ json: { error: err.message, rawOutput: raw, extracted: jsonStr } }];
}

